#include <stdio.h>

#define MAXN 100005
#define MAXQ 50005
#define BLOCK_SIZE 500

static int parent_initial[MAXN];
static int head[MAXN], to[MAXN], next_edge[MAXN];
static int tin[MAXN], tout[MAXN], iter_edge[MAXN], stack_nodes[MAXN];
static int event_time[MAXN], best_event[MAXN];
static int up[20][MAXN];
static int op_type[MAXQ], op_v[MAXQ], op_k[MAXQ];
static int recent[MAXQ];

static int is_ancestor(int a, int b) {
    return a != b && tin[a] <= tin[b] && tin[b] < tout[a];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    parent_initial[1] = 1;
    int edge_count = 0;

    for (int i = 2; i <= n; i++) {
        int p;
        scanf("%d", &p);
        parent_initial[i] = p;

        to[++edge_count] = i;
        next_edge[edge_count] = head[p];
        head[p] = edge_count;
    }

    int timer = 0, top = 0;
    stack_nodes[0] = 1;
    tin[1] = timer++;
    iter_edge[1] = head[1];

    while (top >= 0) {
        int u = stack_nodes[top];
        if (iter_edge[u] != 0) {
            int e = iter_edge[u];
            iter_edge[u] = next_edge[e];

            int v = to[e];
            tin[v] = timer++;
            iter_edge[v] = head[v];
            stack_nodes[++top] = v;
        } else {
            tout[u] = timer;
            top--;
        }
    }

    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        scanf("%d %d", &op_type[i], &op_v[i]);
        if (op_type[i] == 1) {
            scanf("%d", &op_k[i]);
        } else {
            op_k[i] = 0;
        }
    }

    int logn = 1;
    while ((1 << logn) <= n) logn++;

    for (int block_start = 0; block_start < q; block_start += BLOCK_SIZE) {
        int block_end = block_start + BLOCK_SIZE;
        if (block_end > q) block_end = q;

        best_event[1] = event_time[1] ? 1 : 0;
        up[0][1] = 1;

        for (int i = 2; i <= n; i++) {
            int p = parent_initial[i];
            int best = best_event[p];

            up[0][i] = best ? best : p;

            if (event_time[i] > (best ? event_time[best] : 0)) {
                best_event[i] = i;
            } else {
                best_event[i] = best;
            }
        }

        for (int j = 1; j < logn; j++) {
            for (int i = 1; i <= n; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
            }
        }

        int recent_count = 0;

        for (int i = block_start; i < block_end; i++) {
            if (op_type[i] == 2) {
                int v = op_v[i];
                recent[recent_count++] = v;
                event_time[v] = i + 1;
            } else {
                int node = op_v[i];
                int k = op_k[i];
                int answered = 0;

                for (int r = recent_count - 1; r >= 0; r--) {
                    int v = recent[r];
                    if (is_ancestor(v, node)) {
                        node = v;
                        k--;
                        if (k == 0) {
                            printf("%d\n", node);
                            answered = 1;
                            break;
                        }
                    }
                }

                if (!answered) {
                    for (int j = 0; k > 0; j++, k >>= 1) {
                        if (k & 1) node = up[j][node];
                    }
                    printf("%d\n", node);
                }
            }
        }
    }

    return 0;
}
